// Ausgabe des Skripts (Zeilen KEY=WERT) in ein übersichtliches Ergebnis umwandeln
const r = $input.first().json;
const out = String(r.stdout || '');
const val = (k) => (out.match(new RegExp('^' + k + '=(.*)$', 'm')) || [])[1] || null;
const ok = r.code === 0 && val('ERGEBNIS') === 'ok';
const fehler = ok ? null : ((out + '\n' + (r.stderr || '')).match(/FEHLER: .*/) || [r.error?.message || r.stderr || 'unbekannter Fehler'])[0];
return [{ json: {
  ok,
  modus: $('Einstellungen').first().json.mode,
  ordner: val('ORDNER'),
  anzahl: Number(val('ANZAHL') || 0),
  letzte: val('LETZTE'),
  groesse: val('GROESSE'),
  dateien: (val('DATEIEN') || '').trim().split(' ').filter(Boolean),
  fehler,
  ausgabe: out.split('\n').filter((l) => l.startsWith('==') || l.startsWith('FEHLER')).join('\n'),
} }];
